      class: '',
      legroom: false,
      isFree: true
    });
  }
  removeSetupSeat(ai, si) {
    this.setupData.aircrafts[ai].seats.splice(si, 1);
  }
  addAircraft() {
    this.updateData.aircrafts.push({
      _numAircraft: '',
      modello: '',
      seats: [],
      editing: true
    });
  }
